"""Patches the platform folders generated by `flutter create` (CI step).

Adds Android network permissions and sets the display name "NetScan".
Safe to run multiple times.
"""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent

manifest = root / "android/app/src/main/AndroidManifest.xml"
if manifest.exists():
    s = manifest.read_text(encoding="utf-8")
    perms = [
        "android.permission.INTERNET",
        "android.permission.ACCESS_NETWORK_STATE",
        "android.permission.ACCESS_WIFI_STATE",
        "android.permission.CHANGE_WIFI_MULTICAST_STATE",
    ]
    block = "".join(
        f'    <uses-permission android:name="{p}"/>\n' for p in perms if p not in s
    )
    if block:
        s = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + block, s, count=1)
    s = re.sub(r'android:label="[^"]*"', 'android:label="NetScan"', s, count=1)
    manifest.write_text(s, encoding="utf-8")
    print("patched", manifest)

main_cpp = root / "windows/runner/main.cpp"
if main_cpp.exists():
    s = main_cpp.read_text(encoding="utf-8")
    s = s.replace('L"netscan"', 'L"NetScan"')
    s = s.replace("Win32Window::Size size(1280, 720);", "Win32Window::Size size(1280, 820);")
    main_cpp.write_text(s, encoding="utf-8")
    print("patched", main_cpp)

rc = root / "windows/runner/Runner.rc"
if rc.exists():
    s = rc.read_text(encoding="utf-8")
    s = s.replace('"FileDescription", "netscan"', '"FileDescription", "NetScan"')
    s = s.replace('"ProductName", "netscan"', '"ProductName", "NetScan"')
    s = s.replace('"InternalName", "netscan"', '"InternalName", "NetScan"')
    rc.write_text(s, encoding="utf-8")
    print("patched", rc)

cmake = root / "windows/CMakeLists.txt"
if cmake.exists():
    s = cmake.read_text(encoding="utf-8")
    s = re.sub(r'set\(BINARY_NAME "netscan"\)', 'set(BINARY_NAME "NetScan")', s)
    cmake.write_text(s, encoding="utf-8")
    print("patched", cmake)
